    static func edits(_ text:String,language:String)->[(NSRange,String)] {
        guard language.lowercased().replacingOccurrences(of:"_",with:"-").hasPrefix("es") else{return []}
        let ns=text as NSString
        func value(_ raw:String)->String {
            let raw=raw.lowercased().split(whereSeparator:{$0.isWhitespace}).joined(separator:" ")
            if raw.allSatisfy({$0.isNumber}){return raw}
            return words[raw] ?? raw.split(separator:" ").map{words[String($0)] ?? String($0)}.joined()
        }
        return pattern.matches(in:text,range:NSRange(location:0,length:ns.length)).compactMap { m in
            let before=ns.substring(to:m.range.location)
            guard prefix.firstMatch(in:before,range:NSRange(location:0,length:(before as NSString).length)) == nil else{return nil}
            return (m.range,value(ns.substring(with:m.range(at:1)))+","+value(ns.substring(with:m.range(at:2))))
        }
    }
    static func format(_ text:String,language:String)->String {
        var result=text
        for (range,value) in edits(text,language:language).reversed(){result=(result as NSString).replacingCharacters(in:range,with:value)}
        return result
    }
    static func tokens(_ input:[TimedToken],language:String)->[TimedToken] {
        var tokens=input;let joined=input.map(\.text).joined()
        for (range,value) in edits(joined,language:language).reversed(){
            var offset=0;var hits:[(Int,Int)]=[]
            for (i,t) in tokens.enumerated(){let end=offset+(t.text as NSString).length;if offset<NSMaxRange(range) && end>range.location{hits.append((i,offset))};offset=end}
            guard let first=hits.first,let last=hits.last else{continue}
            let combined=tokens[first.0...last.0].map(\.text).joined() as NSString
            let text=combined.replacingCharacters(in:NSRange(location:range.location-first.1,length:range.length),with:value)
            tokens.replaceSubrange(first.0...last.0,with:[TimedToken(text:text,start:tokens[first.0].start,end:tokens[last.0].end)])
        }
        return tokens
    }
